mapper.select:
SELECT SQL_CALC_FOUND_ROWS pp.id AS place_id, pp.partnership_fl, pp.name AS place_name, pp.category_cd AS category_cd, pp.category_group_name, pp.category_name AS category_name, pp.status, pp.tel AS phone, pp.full_address AS address_name, pp.road_address AS road_address_name, pp.x_position AS x, pp.y_position AS y, pp.place_url, (SELECT bf_fileurl FROM g5_board_file gbf INNER JOIN pet_place_file_mapping ppfm ON gbf.bo_table = 'pet_place' AND gbf.wr_id = ppfm.pfm_id WHERE ppfm.place_id = pp.id) AS image_url, pp.opening_hours, IFNULL((SELECT CAST(AVG(point) AS signed integer) FROM pet_review WHERE place_id = pp.id), 0) AS point, IFNULL((SELECT COUNT(*) FROM pet_review WHERE del_fl = 0 AND place_id = pp.id), 0) AS review_count FROM pet_place pp WHERE pp.del_fl = 0
AND pp.category_cd = #{categoryCd}
AND ((pp.name LIKE CONCAT('%', #{searchKeyword}, '%')) OR (pp.road_address LIKE CONCAT('%', #{searchKeyword}, '%')))
ORDER BY pp.partnership_fl DESC, ST_Distance_Sphere( POINT(#{longitude}, #{latitude}), POINT(CAST(pp.x_position AS DECIMAL(15,12)), CAST(pp.y_position AS DECIMAL(15,12))) )
ORDER BY pp.partnership_fl DESC, pp.sido_code
LIMIT #{pageNo}, #{pageSize};

SELECT
    id, name, SUBSTRING_INDEX(full_address, ' ', 2) AS full_address,x_position, y_position
FROM pet_place;

mapper.update:
UPDATE pet_place
SET
    x_position = #{xPosition},
    y_position = #{yPosition}
WHERE id = #{placeId};
